const TERMS = [
  { label: '시작가', value: '홈페이지 80만원부터', note: '웹앱·자동화·AI는 상담 후 견적' },
  { label: '제작 기간', value: '상담 후 안내', note: '만들 범위에 따라 달라집니다' },
  { label: '진행 가능 건수', value: '월 3~4건', note: '한 곳에 충분히 쓰기 위해서입니다' },
]

export default function Includes() {
  useEffect(() => {
    const fadeObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible')
            fadeObserver.unobserve(entry.target)
          }
        })
      },
      { threshold: 0.1 }
    )

    const section = document.getElementById('includes')
    if (section) {
      section.querySelectorAll('.fade-up').forEach((el) => {
        const parent = el.parentElement
        if (parent) {
          const siblings = Array.from(parent.children).filter((c) => c.classList.contains('fade-up'))
          const siblingIndex = siblings.indexOf(el)
          ;(el as HTMLElement).style.transitionDelay = `${siblingIndex * 80}ms`
        }
        fadeObserver.observe(el)
      })
    }

    return () => fadeObserver.disconnect()
  }, [])

  return (
    <section id="includes" className="py-20 md:py-28 bg-[#0E3260]">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-14">
          <p className="text-skyblue font-semibold text-sm mb-3 fade-up">홈페이지 기본 구성</p>
          <h2 className="text-2xl sm:text-3xl md:text-4xl font-extrabold text-white fade-up leading-[1.4] break-keep">
            이건 기본으로 들어갑니다
          </h2>
          <p className="text-base text-white/70 mt-4 max-w-2xl mx-auto fade-up break-keep">
            따로 요청하지 않으셔도 처음부터 포함되는 것들입니다.
          </p>
        </div>

        {/* 포함 항목 5칸 */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-8 lg:gap-6">
          {ITEMS.map((item) => (
            <div key={item.title} className="text-center fade-up">
              <div className="w-14 h-14 rounded-xl bg-white/10 text-skyblue flex items-center justify-center mb-5 mx-auto">
                <svg className="w-7 h-7" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  {item.icon}
                </svg>
              </div>
              <h3 className="text-lg font-bold text-white mb-2.5 break-keep">{item.title}</h3>
              <p className="text-white/70 text-sm break-keep">{item.desc}</p>
            </div>
          ))}
        </div>

        {/* 시작가 · 기간 · 캐파 */}
        <div className="mt-16 pt-12 border-t border-white/15">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-8 text-center">
            {TERMS.map((t) => (
              <div key={t.label} className="fade-up">
                <p className="text-skyblue text-sm font-semibold mb-2">{t.label}</p>
                <p className="text-xl md:text-2xl font-extrabold text-white mb-1.5 break-keep">{t.value}</p>
                <p className="text-white/70 text-sm break-keep">{t.note}</p>
              </div>
            ))}
          </div>

          <p className="mt-10 text-center text-white/60 text-xs break-keep fade-up">
            부가세 별도 · 가격은 만들 구성과 기능에 따라 달라집니다 · 납품 후 유지보수와 기능 추가 작업은 범위에 따라 별도 견적입니다
          </p>
        </div>
      </div>
    </section>
  )
}
